BEGIN;
CREATE TABLE IF NOT EXISTS compliance_identities(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,email TEXT NOT NULL,password_hash TEXT NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','manager','analyst')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,email));
CREATE UNIQUE INDEX IF NOT EXISTS compliance_identity_login_idx ON compliance_identities(tenant_id,lower(email));
CREATE TABLE IF NOT EXISTS compliance_sessions(session_digest TEXT PRIMARY KEY CHECK(session_digest ~ '^[a-f0-9]{64}$'),identity_id UUID REFERENCES compliance_identities(id) ON DELETE CASCADE,identity_email TEXT NOT NULL,tenant_id TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS compliance_session_identity_idx ON compliance_sessions(identity_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS compliance_sources(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,source_uri TEXT NOT NULL,publisher TEXT NOT NULL,jurisdiction TEXT NOT NULL,effective_at TIMESTAMPTZ NOT NULL,retrieved_at TIMESTAMPTZ NOT NULL,source_version TEXT NOT NULL,content_digest TEXT NOT NULL,source_provenance JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,source_id,source_version,content_digest));
CREATE TABLE IF NOT EXISTS policy_versions(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,policy_key TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',owner_id TEXT NOT NULL,reviewer_id TEXT,approver_id TEXT,title TEXT NOT NULL,body_digest TEXT NOT NULL,retain_until TIMESTAMPTZ,legal_hold BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,policy_key,version));
CREATE TABLE IF NOT EXISTS evidence_links(policy_version_id UUID NOT NULL REFERENCES policy_versions(id),source_id UUID NOT NULL REFERENCES compliance_sources(id),citation TEXT NOT NULL,obligation_ref TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(policy_version_id,source_id,citation));
CREATE TABLE IF NOT EXISTS compliance_evaluations(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,policy_version_id UUID NOT NULL REFERENCES policy_versions(id),scenario_id TEXT NOT NULL,input_digest TEXT NOT NULL,result JSONB NOT NULL,passed BOOLEAN NOT NULL,evaluated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(policy_version_id,scenario_id,input_digest));
CREATE TABLE IF NOT EXISTS compliance_decisions(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,policy_version_id UUID NOT NULL REFERENCES policy_versions(id),from_status TEXT,to_status TEXT NOT NULL,actor_id TEXT NOT NULL,actor_role TEXT NOT NULL,rationale TEXT NOT NULL,evidence_snapshot JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION immutable_compliance_decision() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'compliance decisions are append-only';END$$;
DROP TRIGGER IF EXISTS compliance_decisions_immutable ON compliance_decisions;
CREATE TRIGGER compliance_decisions_immutable BEFORE UPDATE OR DELETE ON compliance_decisions FOR EACH ROW EXECUTE FUNCTION immutable_compliance_decision();
CREATE INDEX IF NOT EXISTS policy_versions_queue_idx ON policy_versions(tenant_id,status,updated_at);
CREATE INDEX IF NOT EXISTS compliance_sources_change_idx ON compliance_sources(tenant_id,source_id,retrieved_at DESC);
COMMIT;
